-- 33_updates.sql : replace 2026-08-27 (Thu -> Hard) with boards generated by
-- TRUE random draw of the 9 blues, then auto-discovered shared attributes
-- (type/arch/based-on/egg-group/habitat/colour) covering all 9 in <=5 clues.
-- Experiment requested to check whether random draw reduces how often blues
-- cluster around evolution lines (this run explicitly excludes any board
-- where two blues share an evolution family). Supersedes 32_updates for this date.

insert into public.daily_puzzles (puzzle_date, pool, clues, hints, tiles) values
  ('2026-08-27', 'gen1',
   '[{"word": "BLUE", "number": 2, "cat": 2, "t": [20, 23], "explain": "They''re all blue."}, {"word": "FOREST", "number": 3, "cat": 4, "t": [7, 8, 14], "explain": "They all live in the same kind of place \u2014 forest."}, {"word": "GRASSLAND", "number": 2, "cat": 4, "t": [16, 24], "explain": "They all live in the same kind of place \u2014 grassland."}, {"word": "AMORPHOUS", "number": 2, "cat": 3, "t": [4, 12], "explain": "They''re all based on the real-world amorphous."}]'::jsonb,
